"""Self-contained, source-linked visual report for observed synthetic experiments."""
from __future__ import annotations

import html
import json
from typing import Any, Mapping, Sequence, cast


def render_report(rows: Sequence[Mapping[str, Any]], metadata: Mapping[str, Any]) -> str:
    """Rows carry label/family/variant/expected/probabilities/state/evidence/error.

    Inputs are rendered as data, never HTML or executable script. The threshold
    control is a probability-only simulation, not the production approval policy.
    """
    data = json.dumps({'rows': list(rows), 'metadata': dict(metadata)}, ensure_ascii=True, allow_nan=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    table = []
    plot = []
    height = 52 + len(rows) * 48
    for index, row in enumerate(rows):
        probabilities = row.get('probabilities', {})
        p = probabilities.get('approve') if isinstance(probabilities, Mapping) else None
        valid = isinstance(p, (int, float)) and not isinstance(p, bool) and 0 <= p <= 1
        label = html.escape(str(row.get('label', 'Unknown')))
        variant = html.escape(str(row.get('variant', 'unknown')))
        expected = html.escape(str(row.get('expected', 'unknown')))
        value = f'{p:.0%}' if valid else 'Unavailable'
        table.append(f'<tr><th><button class="case" data-case="{index}">{label}</button><small>{variant} / expected {expected}</small></th><td>{value}</td><td>{html.escape(str(row.get("choice", "unavailable")))}</td></tr>')
        y = 40 + index * 48
        color = '#2459c4' if row.get('variant') == 'safe' else '#b43d28' if row.get('variant') == 'broken' else '#6d4e96'
        plot.append(f'<text x="0" y="{y+5}" class="plot-label">{label}</text><line x1="310" y1="{y}" x2="830" y2="{y}" stroke="#d3d2c9"/>')
        if valid:
            x = 310 + cast(float, p) * 520
            plot.append(f'<line x1="310" y1="{y}" x2="{x:.1f}" y2="{y}" stroke="{color}" stroke-width="3"/><circle cx="{x:.1f}" cy="{y}" r="6" fill="{color}"/><text x="865" y="{y+5}" class="plot-number">{value}</text>')
        else:
            plot.append(f'<text x="320" y="{y+5}" class="plot-number">UNAVAILABLE</text>')
    svg = f'<svg viewBox="0 0 940 {height}" role="img" aria-label="Observed approval probability by synthetic case. Exact values in the table below."><text x="310" y="14" class="axis">0 / do not approve</text><text x="735" y="14" class="axis">1 / approve</text>{"".join(plot)}</svg>'
    return TEMPLATE.replace('<!--PLOT-->', svg).replace('<!--TABLE-->', ''.join(table)).replace('/*DATA*/', data).replace('<!--MODEL-->', html.escape(str(metadata.get('model', 'Recorded model')))).replace('<!--COUNT-->', str(len(rows)))


TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light"><title>Jev / The fault line</title>
<style>
:root{--paper:#f5f4ed;--ink:#17231f;--muted:#55605b;--line:#b8c0b7;--blue:#2459c4;--red:#b43d28;--purple:#6d4e96}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 Georgia,serif}::selection{background:#d5e9a5;color:#17231f}button,input{font:inherit}button,a,input{outline-offset:5px}a{color:var(--blue);text-underline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--blue)}header,main,footer{max-width:1280px;margin:auto;padding:28px 5vw}.mast{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid var(--ink);padding-bottom:20px;font:600 14px/1.4 Arial,sans-serif;letter-spacing:.08em}.mast a{color:inherit}.wordmark{font-size:24px;letter-spacing:-.04em}.intro{display:grid;grid-template-columns:1.3fr .7fr;gap:64px;align-items:end;padding:44px 0 54px;border-bottom:1px solid var(--ink)}h1{font-weight:400;font-size:clamp(52px,7vw,96px);line-height:.98;letter-spacing:-.04em;margin:0;max-width:10ch}h1 em{font-weight:400;color:var(--red)}.lead{font-size:20px;line-height:1.5;max-width:36ch}.sub{font:14px/1.6 Arial,sans-serif;color:var(--muted)}.legend{display:flex;flex-wrap:wrap;gap:24px;margin:24px 0;font:13px Arial,sans-serif}.legend span{display:flex;align-items:center;gap:8px}.swatch{height:3px;width:22px;background:var(--blue)}.swatch.broken{background:var(--red)}.swatch.injected{background:var(--purple)}h2{font:500 clamp(25px,3vw,38px)/1.2 Georgia,serif;letter-spacing:-.025em;margin:0 0 16px}h3{font:600 16px Arial,sans-serif}.chapter{padding:38px 0;border-bottom:1px solid var(--line)}.chapter-head{display:flex;justify-content:space-between;gap:30px;align-items:start}.chapter-head p{max-width:42ch;margin:0}.plot-wrap{overflow:auto;margin:26px 0 18px}.plot-wrap svg{display:block;width:100%;min-width:670px}.plot-label{font:14px Arial,sans-serif;fill:var(--ink)}.plot-number{font:14px 'Courier New',monospace;fill:var(--ink)}.axis{font:12px Arial,sans-serif;fill:var(--muted)}.experiment{display:grid;grid-template-columns:1fr 1.15fr;gap:36px;margin:30px 0}table{width:100%;border-collapse:collapse;font:14px/1.5 Arial,sans-serif}th,td{text-align:left;padding:13px 8px;border-bottom:1px solid var(--line);vertical-align:top}thead th{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}tbody th{font-weight:400}small{display:block;font:12px/1.5 Arial,sans-serif;color:var(--muted)}.case{color:var(--ink);font-weight:600;border:0;background:transparent;text-align:left;padding:3px 0;cursor:pointer;text-decoration:underline;text-decoration-color:var(--line);text-underline-offset:4px}.case:hover,.case[aria-pressed=true]{color:var(--blue);text-decoration-color:var(--blue)}.inspector{background:#17231f;color:#f5f4ed;padding:26px;min-width:0;align-self:start}.inspector h3{margin:0;font-size:21px}.inspector .sub{color:#b7c6c0}.inspector pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 'Courier New',monospace;margin:18px 0;max-height:420px;overflow:auto}.inspector summary{cursor:pointer;font:14px Arial,sans-serif}.dist{display:flex;height:24px;background:#495a52;margin:20px 0 8px}.dist span{min-width:0;display:block}.dist span:nth-child(1){background:#82a9fa}.dist span:nth-child(2){background:#ed977e}.dist span:nth-child(3){background:#c6b2e1}.dist-label{font:12px/1.6 'Courier New',monospace;color:#edf1ee}.simulator{display:grid;grid-template-columns:1fr 1fr;gap:60px}.simulator label{display:block;font:600 15px Arial,sans-serif}.simulator input{width:100%;accent-color:var(--blue);margin:25px 0 15px}.simulation-result{font:19px/1.6 Georgia,serif;min-height:5em}.simulation-result strong{color:var(--red)}.note{font:14px/1.6 Arial,sans-serif;color:var(--muted);max-width:75ch}.provenance{display:grid;grid-template-columns:1fr 1fr;gap:48px}.provenance p{max-width:65ch}.download{border:1px solid var(--ink);padding:10px 16px;background:transparent;cursor:pointer;font:14px Arial,sans-serif}.download:hover{background:var(--ink);color:var(--paper)}footer{font:13px/1.5 Arial,sans-serif;display:flex;justify-content:space-between;gap:24px;padding-bottom:50px}#raw-evidence{max-height:400px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 monospace}.noscript{padding:12px;border:1px solid var(--line)}@media(max-width:760px){header,main,footer{padding-left:22px;padding-right:22px}.intro,.experiment,.simulator,.provenance{grid-template-columns:1fr;gap:24px}.intro{padding:30px 0}.chapter-head{display:block}.chapter-head p{margin-top:16px}.mast{font-size:11px}.mast .wordmark{font-size:22px}.lead{font-size:18px}.inspector{padding:20px}footer{display:block}h1{max-width:12ch}.plot-wrap{margin-right:-8px}.chapter{padding:30px 0}.simulation-result{min-height:0}}@media(prefers-reduced-motion:no-preference){.case,.download{transition:color .15s,background .15s}}
</style></head><body>
<header><nav class="mast" aria-label="Report"><span class="wordmark">jev.</span><span>EXPERIMENT ATLAS / 001</span><a href="#evidence">Source evidence</a></nav>
<div class="intro"><h1>Where does<br>Jev <em>break?</em></h1><div><p class="lead">A code review model should notice when the code changes. And resist when only the story does.</p><p class="sub"><!--COUNT--> synthetic probes. Four bug families. Recorded API responses.<br>Model: <!--MODEL-->. No production calibration claim.</p></div></div></header>
<main><noscript><p class="noscript">JavaScript is disabled. The observed chart and case results remain readable; interactive inspection and threshold simulation require JavaScript.</p></noscript>
<p class="note" id="observed-findings"></p>
<section class="chapter" aria-labelledby="contrast"><div class="chapter-head"><h2 id="contrast">One change.<br>A different verdict?</h2><p class="note">Same problem, paired code. Each mark is an observed approval probability. A lower broken-case probability is the desired contrast; it is not proof of general accuracy.</p></div>
<div class="legend"><span><i class="swatch"></i>Safe version</span><span><i class="swatch broken"></i>Broken version</span><span><i class="swatch injected"></i>Metadata attack</span></div><div class="plot-wrap"><!--PLOT--></div></section>
<section class="chapter" aria-labelledby="inspect"><div class="chapter-head"><h2 id="inspect">Interrogate the evidence.</h2><p class="note">Select any case. Inspect the exact supplied state, distribution and request provenance. An unavailable response stays unavailable.</p></div><div class="experiment"><table><thead><tr><th scope="col">Synthetic case</th><th scope="col">P(approve)</th><th scope="col">Jev chose</th></tr></thead><tbody><!--TABLE--></tbody></table><aside class="inspector" aria-label="Selected case"><h3 id="case-title">Select a case</h3><p class="sub" id="case-meta">Exact state and model response.</p><div class="dist" id="distribution" aria-hidden="true"></div><div class="dist-label" id="distribution-label"></div><pre id="case-state"></pre><details><summary>Raw response and provenance</summary><pre id="case-evidence"></pre></details></aside></div></section>
<section class="chapter" aria-labelledby="sim"><div class="simulator"><div><h2 id="sim">Raise the bar.<br>See what slips through.</h2><p class="note">Hypothetical probability threshold only. This ignores the deployed policy's other gates and never changes it. Ten designed examples cannot establish calibration.</p></div><div><label for="threshold">Hypothetical P(approve) threshold: <output id="threshold-value">90%</output></label><input type="range" id="threshold" min="0" max="100" value="90" step="1"><div class="simulation-result" id="simulation" aria-live="polite"></div></div></div></section>
<section class="chapter" id="evidence"><div class="provenance"><div><h2>Trace every mark.</h2><p class="note">Hand-authored synthetic labels, not independent maintainer labels. Inputs and returned probabilities are recorded verbatim. Same-model perspectives can agree and still be wrong. No PR code was executed by Jev.</p><button class="download" id="download">Download report evidence / JSON</button></div><div><h3>What this establishes</h3><p class="note">Transport behavior, typed decisions, bug/repair sensitivity and response to adversarial metadata on these cases. It does not establish a false-approval bound, broad accuracy, coverage or production readiness.</p><details><summary>Full experiment record</summary><pre id="raw-evidence"></pre></details></div></div></section>
</main><footer><span>Jev Review / evidence before autonomy</span><span>Static artifact. No analytics. No external scripts.</span></footer>
<script type="application/json" id="report-data">/*DATA*/</script>
<script>
'use strict';
const dataset=JSON.parse(document.getElementById('report-data').textContent),rows=dataset.rows;
const pretty=v=>JSON.stringify(v,null,2),byId=id=>document.getElementById(id);
const complete=rows.filter(r=>typeof (r.probabilities||{}).approve==='number'),heldSafe=complete.filter(r=>r.expected==='approve'&&r.choice!=='approve'),classMiss=complete.filter(r=>r.expected_failure!==r.observed_failure);byId('observed-findings').textContent='Observed in this run: '+heldSafe.length+' safe case(s) not approved; '+classMiss.length+' failure-class mismatches. '+complete.length+' of '+rows.length+' responses available. Inspect the misses as closely as the catches.';
function selectCase(index){const row=rows[index];if(!row)return;document.querySelectorAll('.case').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));byId('case-title').textContent=row.label;byId('case-meta').textContent=row.variant+' / expected: '+row.expected+' / observed: '+row.choice+' | failure class: '+(row.observed_failure||'unavailable')+' / expected: '+(row.expected_failure||'unknown')+(row.error?' / unavailable':'');byId('case-state').textContent=typeof row.state==='string'?row.state:row.state&&Array.isArray(row.state.files)?row.state.files.map(f=>f.path+'\n\n'+f.patch).join('\n\n'):pretty(row.state);byId('case-evidence').textContent=pretty(row.evidence);const dist=byId('distribution');dist.replaceChildren();const probabilities=row.probabilities||{};['approve','hold','review'].forEach(name=>{const p=probabilities[name];if(typeof p==='number'&&p>=0&&p<=1){const span=document.createElement('span');span.style.width=(p*100)+'%';dist.append(span);}});byId('distribution-label').textContent=['approve','hold','review'].map(name=>name+' '+(typeof probabilities[name]==='number'?(probabilities[name]*100).toFixed(1)+'%':'unavailable')).join(' / ');}
function simulate(){const threshold=Number(byId('threshold').value)/100;byId('threshold-value').textContent=Math.round(threshold*100)+'%';let selected=0,unsafe=0,missing=0;for(const row of rows){const p=(row.probabilities||{}).approve;if(typeof p!=='number'){missing++;continue;}if(p>=threshold){selected++;if(row.expected!=='approve')unsafe++;}}const target=byId('simulation');target.replaceChildren();const a=document.createElement('p');a.textContent=selected+' of '+rows.length+' cases meet this threshold.';const b=document.createElement('strong');b.textContent=unsafe+' expected non-approval cases would pass.';const c=document.createElement('p');c.className='note';c.textContent=missing+' unavailable responses. This is a fixture-level simulation, not measured production risk.';target.append(a,b,c);}
document.querySelectorAll('.case').forEach(b=>b.addEventListener('click',()=>selectCase(Number(b.dataset.case))));byId('threshold').addEventListener('input',simulate);byId('raw-evidence').textContent=pretty(dataset);byId('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([pretty(dataset)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='jev-experiment-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});selectCase(0);simulate();
</script></body></html>'''
